import boundarySlugs from './city-boundaries.json';
import { dataUrl } from '$lib/data/data-base';
import { cityBySlug } from '$lib/data/cities';

// Generated by `scripts/update-data.mjs`. Consulted before fetching so a prerender never requests
// a boundary that was never emitted.
const HAS_BOUNDARY = new Set<string>(boundarySlugs);

/**
 * A city boundary carries the focus city's display name as a foreign member, so the basemap can
 * emphasise *that one* label (bold + black) without a separate prop threaded through every map
 * route. The boundary polygon alone is too coarse — a modern municipality (e.g. Alkmaar) contains
 * many villages, all inside the polygon — so `label-clip.js` matches the label by name, not by
 * `within` alone. Foreign members on a FeatureCollection are ignored by MapLibre's `within`.
 */
export type CityBoundary = GeoJSON.FeatureCollection & { cityName?: string };

// Boundaries are immutable build artefacts, so one parse per slug is enough for the session. This
// is not just about bytes: without it every navigation hands the map components a fresh object,
// and their clip effect — which compares by reference — re-filters on metric and type switches
// where the city has not changed at all.
const cache = new Map<string, Promise<CityBoundary | null>>();

// The settled values from `cache`, for the one caller that has to decide *synchronously*:
// `active-dataset` seeds its state from this, so a city visited earlier in the session — or warmed
// by the hover prefetch — has its polygon in hand before the map is constructed, and the clip goes
// into the initial style instead of a symbol re-layout after first paint. The polygons are
// simplified to ~100 m (2–9 KB each), so keeping the parsed ones for a session costs nothing.
const settled = new Map<string, CityBoundary | null>();

/** The boundary for `slug` if it has already been fetched this session, else null. */
export function cachedCityBoundary(slug: string): CityBoundary | null {
	return settled.get(slug) ?? null;
}

export const boundaryPathFor = (slug: string) => dataUrl(`/data/cities/${slug}-boundary.geojson`);

/** The simplified city polygon the basemap clips its labels to, or null if there is none. */
export function loadCityBoundary(
	fetch: typeof globalThis.fetch,
	slug: string
): Promise<CityBoundary | null> {
	if (!HAS_BOUNDARY.has(slug)) return Promise.resolve(null);
	let pending = cache.get(slug);
	if (!pending) {
		pending = fetch(boundaryPathFor(slug))
			.then((res) => (res.ok ? res.json() : null))
			.then((fc: CityBoundary | null) => {
				// Tag the polygon with the focus city name so the basemap can bold just its label.
				if (fc) fc.cityName = cityBySlug[slug]?.name;
				settled.set(slug, fc);
				return fc;
			})
			// A failed fetch must not poison the slug for the rest of the session.
			.catch(() => {
				cache.delete(slug);
				settled.delete(slug);
				return null;
			});
		cache.set(slug, pending);
	}
	return pending;
}
